import React, { useState } from 'react';
import { Camera, User, Mail, Lock, UserCircle } from 'lucide-react';

const SignInPage = ({ onSignIn, onNavigate }) => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
    role: 'user'
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (formData.password !== formData.confirmPassword) {
      setError('كلمات المرور غير متطابقة');
      return;
    }

    if (formData.password.length < 6) {
      setError('يجب أن تكون كلمة المرور 6 أحرف على الأقل');
      return;
    }

    setLoading(true);
    const result = await onSignIn({
      name: formData.name,
      email: formData.email,
      password: formData.password,
      role: formData.role
    });
    setLoading(false);

    if (!result.success) {
      setError(result.error || 'فشل التسجيل. يرجى المحاولة مرة أخرى.');
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#0a1628] via-[#1a2942] to-[#0a1628] flex items-center justify-center p-4" dir="rtl">
      <div className="bg-[#1a2942] rounded-2xl shadow-2xl p-8 w-full max-w-md animate-fadeIn border border-[#00d4ff]/30">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-[#00d4ff] rounded-lg flex items-center justify-center mx-auto mb-4">
            <Camera className="w-10 h-10 text-[#0a1628]" />
          </div>
          <h2 className="text-3xl font-bold text-white">إنشاء حساب</h2>
          <p className="text-gray-300 mt-2">انضم إلى مَكّمن للبدء</p>
        </div>

        {error && (
          <div className="bg-red-500/20 border border-red-500 text-red-400 p-3 rounded-lg mb-4 text-sm">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">الاسم الكامل</label>
            <div className="relative">
              <User className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                name="name"
                required
                className="w-full pr-10 pl-4 py-3 bg-[#0f1f3d] border border-[#00d4ff]/30 text-white rounded-lg focus:ring-2 focus:ring-[#00d4ff] focus:border-transparent transition"
                placeholder="أحمد محمد"
                value={formData.name}
                onChange={handleChange}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">البريد الإلكتروني</label>
            <div className="relative">
              <Mail className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="email"
                name="email"
                required
                className="w-full pr-10 pl-4 py-3 bg-[#0f1f3d] border border-[#00d4ff]/30 text-white rounded-lg focus:ring-2 focus:ring-[#00d4ff] focus:border-transparent transition"
                placeholder="ahmed@example.com"
                value={formData.email}
                onChange={handleChange}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">كلمة المرور</label>
            <div className="relative">
              <Lock className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="password"
                name="password"
                required
                minLength={6}
                className="w-full pr-10 pl-4 py-3 bg-[#0f1f3d] border border-[#00d4ff]/30 text-white rounded-lg focus:ring-2 focus:ring-[#00d4ff] focus:border-transparent transition"
                placeholder="••••••••"
                value={formData.password}
                onChange={handleChange}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">تأكيد كلمة المرور</label>
            <div className="relative">
              <Lock className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="password"
                name="confirmPassword"
                required
                minLength={6}
                className="w-full pr-10 pl-4 py-3 bg-[#0f1f3d] border border-[#00d4ff]/30 text-white rounded-lg focus:ring-2 focus:ring-[#00d4ff] focus:border-transparent transition"
                placeholder="••••••••"
                value={formData.confirmPassword}
                onChange={handleChange}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">اختر الدور</label>
            <div className="relative">
              <UserCircle className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <select
                name="role"
                className="w-full pr-10 pl-4 py-3 bg-[#0f1f3d] border border-[#00d4ff]/30 text-white rounded-lg focus:ring-2 focus:ring-[#00d4ff] focus:border-transparent transition appearance-none"
                value={formData.role}
                onChange={handleChange}
              >
                <option value="user">مستخدم - عرض ورفع</option>
                <option value="admin">مدير - وصول كامل</option>
              </select>
            </div>
            <p className="text-xs text-gray-400 mt-1">
              {formData.role === 'admin' 
                ? 'وصول كامل لإدارة الفروع والكاميرات والمستخدمين' 
                : 'الوصول إلى لوحة المعلومات والتقارير ورفع الفيديوهات'}
            </p>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-[#00d4ff] text-[#0a1628] py-3 rounded-lg hover:bg-[#00b8e6] font-bold shadow-md hover:shadow-lg transition-all disabled:bg-gray-600 disabled:cursor-not-allowed"
          >
            {loading ? 'جاري إنشاء الحساب...' : 'إنشاء حساب'}
          </button>
        </form>

        <div className="relative my-6">
          <div className="absolute inset-0 flex items-center">
            <div className="w-full border-t border-[#00d4ff]/30"></div>
          </div>
          <div className="relative flex justify-center text-sm">
            <span className="px-2 bg-[#1a2942] text-gray-400">هل لديك حساب بالفعل؟</span>
          </div>
        </div>

        <button 
          onClick={() => onNavigate('login')} 
          className="w-full text-[#00d4ff] hover:text-white font-medium py-2 transition-colors"
        >
          تسجيل الدخول إلى حسابك
        </button>

        <button 
          onClick={() => onNavigate('home')} 
          className="w-full text-gray-400 hover:text-gray-300 font-medium py-2 mt-2 transition-colors text-sm"
        >
          → العودة للرئيسية
        </button>
      </div>
    </div>
  );
};

export default SignInPage;
